'use strict';
(()=>{const root=document.documentElement;let phosphor='green',crt=true;try{phosphor=localStorage.getItem('niti-display-phosphor')==='amber'?'amber':'green';crt=localStorage.getItem('niti-display-crt')!=='off';}catch{}const color=document.getElementById('phosphorSwitch'),scan=document.getElementById('crtSwitch');function paint(){root.dataset.phosphor=phosphor;root.dataset.crt=crt?'on':'off';color.textContent=phosphor==='amber'?'Цвет: янтарный':'Цвет: зелёный';color.setAttribute('aria-pressed',String(phosphor==='amber'));scan.textContent=crt?'ЭЛТ: вкл':'ЭЛТ: выкл';scan.setAttribute('aria-pressed',String(crt));document.querySelector('meta[name="theme-color"]').content=phosphor==='amber'?'#11110b':'#09110c';}color.addEventListener('click',()=>{phosphor=phosphor==='green'?'amber':'green';paint();try{localStorage.setItem('niti-display-phosphor',phosphor);}catch{}});scan.addEventListener('click',()=>{crt=!crt;paint();try{localStorage.setItem('niti-display-crt',crt?'on':'off');}catch{}});paint();})();
